async function main() {
  let inserted = 0, updated = 0, errors = 0;

  for (const h of hotels) {
    try {
      const starRating = ratingMap[h.HotelRating] ?? 0;
      await p.tbo_hotel_master.upsert({
        where: { tbo_hotel_code: h.HotelCode },
        create: {
          tbo_hotel_code: h.HotelCode,
          tbo_city_code: CITY_CODE,
          hotel_name: h.HotelName,
          hotel_address: h.Address,
          city_name: h.CityName,
          star_rating: starRating,
          hotel_image_url: '',
          description: '',
          check_in_time: '14:00',
          check_out_time: '11:00',
          facilities: '[]',
          status: 1,
        },
        update: {
          tbo_city_code: CITY_CODE,
          hotel_name: h.HotelName,
          hotel_address: h.Address,
          city_name: h.CityName,
          star_rating: starRating,
          status: 1,
        },
      });
      inserted++;
    } catch (e) {
      console.error(`Error on ${h.HotelCode}: ${e.message}`);
      errors++;
    }
  }

  console.log(`\nDone: ${inserted} upserted, ${errors} errors`);

  const count = await p.tbo_hotel_master.count({ where: { tbo_city_code: CITY_CODE } });
  console.log(`tbo_hotel_master for city 130990: ${count} rows`);

  process.exit(0);
}

main().catch(e => { console.error(e); process.exit(1); });
